/*
 * One player's result record: a snapshot of GwPlayer taken by PResPlayerCreate (partyresult.c
 * 0x47C). All bonus-star / ranking / tie work is done on this copy; partyresultdll never writes
 * GwPlayer or GwSystem. Slot order is PResPlayerOrder[] (team mode: team 0 in slots 0,1, team 1
 * in slots 2,3). size 0xF6 (GC), all s16, no pointers. Names are offsets until a fork names them.
 */
typedef struct PResPlayer_s {
    /* 0x000 */ s16 unk000;     /* charNo (GwPlayer 0x00 bits 4..1) */
    /* 0x002 */ s16 unk002;     /* playerNo: the GwPlayer index (PResPlayerOrder[i]) */
    /* 0x004 */ s16 unk004;     /* star: GwPlayer.star (0x34); ResultBonusExec adds bonus stars here */
    /* 0x006 */ s16 unk006;     /* coin: GwPlayer.coin (0x20) */
    /* 0x008 */ s16 unk008;     /* tieWinF: 0, set 1 for the dice-block tie winner; added to the rank key */
    /* 0x00A */ s16 unk00A[3];  /* bonus metric [b]: coinTotalMg (0x22), coinMax (0x26), hatenaMasu (0x17, s8) */
    /* 0x010 */ s16 unk010[10]; /* detail page: star, coin, coinTotalMg, coinMax, blue(0x14), red(0x15),
                                   capsuleMasu(0x16), hatena(0x17), kupa(0x18), donkey(0x1E) (pre-bonus;
                                   PResStatDetailCreate 0xE2B4 overwrites [0],[1] with the post-bonus
                                   unk004/unk006 before the detail page is built) */
    /* 0x024 */ s16 unk024;     /* turnMax (GwSystem 0x05) */
    /* 0x026 */ s16 unk026[2][52]; /* per-turn graphs, [0] stars / [1] coins (the old unk08E is
                                      unk026[1]: StatGraphDraw indexes [type] with mulli 0x68, and
                                      only a [2][52] declaration reproduces its address arithmetic).
                                      [0][0] GwPlayer byte 0x03, [0][1..turnMax-1] starStat[],
                                      [0][turnMax] star, [0][turnMax+1] post-bonus star
                                      (PResStatDetailCreate); [1][0] 10, [1][1..turnMax-1] coinStat[],
                                      [1][turnMax] coin, [1][turnMax+1] */
} PRES_PLAYER;

#define PRES_PLAYER_MAX 4

